import subprocess
def run(args):
    r = subprocess.run(["timeout","2","./executable"]+args, capture_output=True, text=True, timeout=5)
    return (r.stdout, r.stderr, r.returncode)

def t(expr, base=None, fix=None, angle=None):
    args=[]
    if fix is not None: args+=["-f",str(fix)]
    if base is not None: args+=["-b",str(base)]
    if angle is not None: args+=["-a",str(angle)]
    args+=[expr]
    out,err,code=run(args)
    print(f"expr={expr!r} base={base} fix={fix} angle={angle} => out={out!r} err={err!r} code={code}")

# fraction behavior non-10
for fix in [10,5,2,1]:
    for expr in ["1","1.5","0.5","255.255","1/3"]:
        t(expr, base=16, fix=fix)
print("--- base10 fix ---")
for fix in [10,5,2,1]:
    for expr in ["1","1.5","0.5","1/3"]:
        t(expr, base=10, fix=fix)
print("--- negative ---")
for expr in ["-1","-255","-1.5","-0.5"]:
    t(expr, base=10)
    t(expr, base=16)
    t(expr, base=2)
PY"}

