import subprocess
def run(args):
    r = subprocess.run(["timeout","2","./executable"]+args, capture_output=True, text=True, timeout=5)
    return r.stdout

def show(expr, base):
    out=run(["-b",str(base),"--",expr] if expr.startswith("-") else ["-b",str(base),expr])
    s=out.rstrip("\n")
    print(f"base={base} expr={expr!r} => {out!r} len_nolf={len(s)} chars:" + " ".join(f"{i}:{repr(c)}" for i,c in enumerate(s)))

for expr in ["-10","-100","-1000","-10000","-1000000","-1","-255"]:
