        t(expr, 2, fix)
print("--- inexact with trailing zero possibility ---")
for expr in ["1/3","2/3","1/7","1/10","0.1"]:
    for fix in [10,5,3,2]:
        t(expr, 16, fix)
        t(expr, 2, fix)
