    s = re.sub(r'\s+', '', expr)
    if s == "":
        return 0.0
    open_c = s.count('(')
    close_c = s.count(')')
    if close_c > open_c:
        raise EvalError("Syntax Error: Mismatched parentheses!")
    elif open_c > close_c:
