        if typ=='CONST' and idx+1<len(tokens) and tokens[idx+1][0]=='LPAREN':
            raise EvalError(f"Syntax Error: Unknown function '{val}'")
    for idx,(typ,val) in enumerate(tokens):
        if typ=='UNKNOWN' and idx+1<len(tokens) and tokens[idx+1][0]=='LPAREN':
            raise EvalError(f"Syntax Error: Unknown function '{val}'")
    parser = Parser(tokens, angle, prev_ans, has_prev)
    parser.is_repl = is_repl
    try:
