#!/usr/bin/env python3
import sys, os, math, random, re

VERSION_STR = "eva 0.3.1"
HELP_CLI = """Calculator REPL similar to bc(1)

Usage: executable [OPTIONS] [INPUT]

Arguments:
  [INPUT]  Optional expression string to run eva in command mode

Options:
  -f, --fix <FIX>                Number of decimal places in output (1 - 64) [default: 10]
  -b, --base <RADIX>             Radix of calculation output (1 - 36) [default: 10]
  -a, --angle_unit <angle_unit>  Angle unit [default: degree] [possible values: degree, radian, gradian]
  -h, --help                     Print help
  -V, --version                  Print version
"""

CONSTANTS_LIST = ["e", "pi"]
FUNCTIONS_LIST = ["sin","cos","tan","csc","sec","cot","sinh","cosh","tanh","asin","acos","atan","acsc","asec","acot","ln","log2","log10","sqrt","ceil","floor","abs","log","nroot","exp","exp2","deg","rad","round"]
OPERATORS_LIST = ["+", "-", "*", "/", "^", "%", "!"]
random.shuffle(CONSTANTS_LIST)
random.shuffle(FUNCTIONS_LIST)
random.shuffle(OPERATORS_LIST)

_help_expr_cache = None
def get_help_expr():
    global _help_expr_cache
    if _help_expr_cache is None:
        const_line = "".join(f"{c:>8}" for c in CONSTANTS_LIST)
        func_lines = []
        for i in range(0, len(FUNCTIONS_LIST), 9):
            chunk = FUNCTIONS_LIST[i:i+9]
            line = "".join(f"{f:>8}" for f in chunk)
            func_lines.append(line)
        func_block = "\n".join(func_lines)
        op_line = " ".join(OPERATORS_LIST)
        _help_expr_cache = f"Constants\n{const_line}\n\nFunctions\n{func_block}\n\nOperators\n{op_line}\n\n"
    return _help_expr_cache

MAX_VAL_STR = ""

def print_help_cli():
    sys.stdout.write(HELP_CLI)

def print_version():
    sys.stdout.write(VERSION_STR + "\n")

def parse_fix_value(val):
    if val == "":
        return None, f"error: invalid value '' for '--fix <FIX>': cannot parse integer from empty string\n\nFor more information, try '--help'.\n"
    if not re.fullmatch(r'\+?\d+', val):
        return None, f"error: invalid value '{val}' for '--fix <FIX>': invalid digit found in string\n\nFor more information, try '--help'.\n"
    try:
        iv = int(val)
    except:
        return None, f"error: invalid value '{val}' for '--fix <FIX>': invalid digit found in string\n\nFor more information, try '--help'.\n"
    if not (1 <= iv <= 64):
        return None, f"error: invalid value '{val}' for '--fix <FIX>': {val} is not in 1..=64\n\nFor more information, try '--help'.\n"
    return iv, None

def parse_base_value(val):
    if val == "":
        return None, f"error: invalid value '' for '--base <RADIX>': cannot parse integer from empty string\n\nFor more information, try '--help'.\n"
    if not re.fullmatch(r'\+?\d+', val):
        return None, f"error: invalid value '{val}' for '--base <RADIX>': invalid digit found in string\n\nFor more information, try '--help'.\n"
    try:
        iv = int(val)
    except:
        return None, f"error: invalid value '{val}' for '--base <RADIX>': invalid digit found in string\n\nFor more information, try '--help'.\n"
    if not (1 <= iv <= 36):
        return None, f"error: invalid value '{val}' for '--base <RADIX>': {val} is not in 1..=36\n\nFor more information, try '--help'.\n"
    return iv, None

def parse_angle_value(val):
    valid = ["degree","radian","gradian"]
    if val in valid:
        return val, None
    def lev(a,b):
        n,m=len(a),len(b)
        dp=[[0]*(m+1) for _ in range(n+1)]
        for i in range(n+1): dp[i][0]=i
        for j in range(m+1): dp[0][j]=j
        for i in range(1,n+1):
            for j in range(1,m+1):
