    if xdg:
        return os.path.join(xdg, "eva")
    else:
        home = os.path.expanduser("~")
        return os.path.join(home, ".local", "share", "eva")

def get_cache_dir():
    xdg = os.environ.get("XDG_CACHE_HOME")
    if xdg:
        return os.path.join(xdg, "eva")
    else:
        home = os.path.expanduser("~")
        return os.path.join(home, ".cache", "eva")

def main():
    argv = sys.argv[1:]
    try:
        res, err, code = parse_cli(argv)
    except SystemExit as e:
        sys.exit(e.code)
    if err is not None:
        sys.stderr.write(err)
        sys.exit(code)
    fix, base, angle, input_expr = res
    if input_expr is None or input_expr == "":
        run_repl(fix, base, angle)
    else:
        out, is_err, _, _, is_help = evaluate_input(input_expr, fix, base, angle, 0.0, False, False)
        if is_err:
            if is_help:
                sys.stderr.write(out)
                sys.exit(1)
            else:
                sys.stderr.write(out + "\n")
                sys.exit(1)
        else:
            sys.stdout.write(out + "\n")
            sys.exit(0)

def run_repl(fix, base, angle):
    data_dir = get_data_dir()
    cache_dir = get_cache_dir()
    hist_file = os.path.join(data_dir, "history.txt")
    prev_file = os.path.join(cache_dir, "previous_ans.txt")
    try:
        os.makedirs(data_dir, exist_ok=True)
    except:
        pass
    try:
        os.makedirs(cache_dir, exist_ok=True)
    except:
        pass
    hist_exists = os.path.isfile(hist_file)
    existing_history = []
    if hist_exists:
        try:
            with open(hist_file, 'r', encoding='utf-8', errors='ignore') as f:
                lines = f.read().splitlines()
                if lines and lines[0].strip() == "#V2":
                    existing_history = lines[1:]
                else:
                    existing_history = lines
        except:
            existing_history = []
    else:
        sys.stdout.write("No previous history.\n")
        sys.stdout.flush()
    if not os.path.isfile(prev_file):
        try:
            with open(prev_file, 'w', encoding='utf-8') as f:
                f.write("0")
        except:
            pass
    prev_ans = 0.0
    has_prev = False
    new_history = []
    last_hist = existing_history[-1] if existing_history else None
    def add_history(line):
        nonlocal last_hist
        if line.strip() == "":
            return
        if line == last_hist:
            return
        new_history.append(line)
        last_hist = line
    def save_history():
        if not new_history:
            return
        all_hist = existing_history + new_history
        try:
            os.makedirs(data_dir, exist_ok=True)
            with open(hist_file, 'w', encoding='utf-8') as f:
                f.write("#V2\n")
                for h in all_hist:
                    f.write(h + "\n")
            try:
                os.chmod(hist_file, 0o600)
            except:
                pass
        except:
            pass
    def update_prev_file(val):
        s = format_prev_ans(val, fix)
        try:
            os.makedirs(cache_dir, exist_ok=True)
            with open(prev_file, 'w', encoding='utf-8') as f:
                f.write(s + "\n")
        except:
            pass
    is_tty = sys.stdin.isatty()
    if is_tty:
        while True:
            try:
                sys.stdout.write("> ")
                sys.stdout.flush()
                line = sys.stdin.readline()
                if line == "":
                    sys.stdout.write("\n")
                    break
                if line.endswith("\n"):
                    line_content = line[:-1]
                    if line_content.endswith("\r"):
                        line_content = line_content[:-1]
                else:
                    line_content = line
                out, is_err, new_prev, new_has, is_help = evaluate_input(line_content, fix, base, angle, prev_ans, has_prev, True)
                if is_help:
                    sys.stdout.write(out)
                    add_history(line_content)
                elif is_err:
                    sys.stdout.write(out + "\n")
                    add_history(line_content)
                else:
                    sys.stdout.write(out + "\n")
                    add_history(line_content)
                    prev_ans, has_prev = new_prev, new_has
                    update_prev_file(prev_ans)
            except KeyboardInterrupt:
                sys.stdout.write("\n")
                continue
            except EOFError:
                break
        save_history()
    else:
        data = sys.stdin.read().splitlines()
        for line_content in data:
            out, is_err, new_prev, new_has, is_help = evaluate_input(line_content, fix, base, angle, prev_ans, has_prev, True)
