{"command": "python3 <<'PY'
import subprocess, os, math, random
def clean():
    for p in ["/home/agent/.local/share/eva/history.txt","/home/agent/.cache/eva/previous_ans.txt"]:
        try: os.remove(p)
        except: pass
    try: os.rmdir("/home/agent/.local/share/eva")
    except: pass
    try: os.rmdir("/home/agent/.cache/eva")
    except: pass
def run_both(expr, angle="degree"):
    args=["-a",angle,expr] if angle!="degree" else [expr]
    # handle leading -? expr starts with letter, no need --
    clean()
    r1=subprocess.run(["timeout","2","./executable"]+args, capture_output=True, text=True, timeout=5)
    clean()
    r2=subprocess.run(["timeout","2","./eva.py"]+args, capture_output=True, text=True, timeout=5)
    clean()
    return r1,r2

fails=0
for _ in range(50):
    # random trig
    v=random.uniform(-360,360)
    f=random.choice(["sin","cos","tan","asin","acos","atan","sinh","cosh","exp","ln","sqrt"])
    # ensure domain? For asin etc., need -1..1, for ln/sqrt need >0
    if f in ["asin","acos"]:
        v=random.uniform(-1,1)
    elif f in ["ln","sqrt","log2","log10"]:
        v=random.uniform(0.01,10)
    expr=f"{f}({v:.5f})"
    for angle in ["degree","radian"]:
        r1,r2=run_both(expr, angle)
        if r1.stdout!=r2.stdout or r1.stderr!=r2.stderr:
            print(f"DIFF {expr} angle {angle} orig out={r1.stdout!r} err={r1.stderr!r} new out={r2.stdout!r} err={r2.stderr!r}")
            fails+=1
            if fails>5: break
    if fails>5: break
print(f"fails={fails}")
PY"}

